def uv(lang):
 X=lambda w:120+(w-200)*4.4;Y=lambda a:290-a*250
 s=F.start(340)+line(X(200),Y(0),X(352),Y(0),1.5)+line(X(200),Y(0),X(200),Y(1.0),1.5)
 for w in range(200,351,10):s+=line(X(w),Y(0),X(w),Y(0)+5)+t(X(w),Y(0)+20,str(w),10)
 for k in range(0,11):a=k/10;s+=line(X(200)-5,Y(a),X(200),Y(a))+t(X(200)-20,Y(a)+4,f'{a:.1f}',10)
 pts=[]
 for i in range(0,1501):
  w=200+i/10;a=0.83*math.exp(-((w-222)/12)**2) if w<222 else 0.83*math.exp(-((w-222)/16)**2)
  if w<222:a=max(a,0.14+(w-200)/22*0.69 if w>=200 else 0)
  pts.append(f'{X(w):.1f},{Y(a):.1f}')
 s+=f'<polyline points="{" ".join(pts)}" fill="none" stroke="#222" stroke-width="2"/>'+t(X(232),Y(0.9),'λmax = 222',12)
 s+=t(X(300),Y(0.5),'CH₂=CH—C=CH₂',13)+line(X(300)+22,Y(0.5)+6,X(300)+22,Y(0.5)+18)+t(X(300)+22,Y(0.5)+32,'CH₃',12)+t(X(300),Y(0.22),K(lang,'(solvent = methanol)','(محلل = میتھانول)','(محلل = میتانول)'),12)
 s+=f'<text x="60" y="{Y(0.5)}" transform="rotate(-90 60 {Y(0.5)})" text-anchor="middle" font-family="Arial" font-size="12">{K(lang,"absorbance","جذب","جذب")}</text>'+t(X(275),Y(0)+40,'λ(nm)',12)
 return s+'</svg>'
def vib(lang):
 s=F.start(220)+t(200,20,K(lang,'Stretching vibrations','کھنچاؤ والے ارتعاشات','د کشېدو اهتزازات'),13,'#ad1457')+t(620,20,K(lang,'Bending vibrations','جھکاؤ والے ارتعاشات','د کږېدو اهتزازات'),13,'#ad1457')
 def ch2(x,y,lab,arr):
  o=f'<circle cx="{x}" cy="{y}" r="14" fill="#90a4ae"/>'+t(x,y+5,'C',12)+f'<circle cx="{x-30}" cy="{y+34}" r="9" fill="#e0e0e0" stroke="#555"/><circle cx="{x+30}" cy="{y+34}" r="9" fill="#e0e0e0" stroke="#555"/>'+line(x-8,y+10,x-24,y+28)+line(x+8,y+10,x+24,y+28)+t(x-30,y+38,'H',10)+t(x+30,y+38,'H',10)
  for (ax,ay,bx,by) in arr:o+=line(x+ax,y+ay,x+bx,y+by,1.5,'#c62828')+f'<circle cx="{x+bx}" cy="{y+by}" r="2.5" fill="#c62828"/>'
  return o+t(x,y+70,lab,11)
 s+=ch2(130,60,K(lang,'Symmetrical','متشاکل','متناظر'),[(-38,40,-50,52),(38,40,50,52)])+ch2(270,60,K(lang,'Asymmetrical','غیر متشاکل','نامتناظر'),[(-38,40,-50,52),(38,40,26,28)])
 for x,lab,arr in ((470,K(lang,'Rocking','جھولنا','ټوکېدل'),[(-40,30,-46,18),(20,46,8,52)]),(580,K(lang,'Scissoring','قینچی نما','قیچي'),[(-40,30,-28,24),(40,30,28,24)]),(690,K(lang,'Wagging','ہلنا','ښورېدل'),[(-30,48,-30,58),(30,48,30,58)]),(800,K(lang,'Twisting','بل کھانا','تاوېدل'),[(-30,48,-30,58),(30,48,30,26)])):
  s+=ch2(x,60,lab,arr)
 s+=t(200,200,'',1)
 return s+'</svg>'

